package com.iotdevice.firmware.http

import java.net.{Socket, InetSocketAddress}
import java.io.{BufferedReader, InputStreamReader, OutputStream}
import java.util.concurrent.{ConcurrentLinkedQueue, atomic}
import scala.collection.mutable

object HttpConfig {
  val MAX_POOL_SIZE = 8
  val CONNECT_TIMEOUT_MS = 5000
  val READ_TIMEOUT_MS = 10000
  val FIRMWARE_ENDPOINT = "/api/v2/telemetry"
}

class ConnectionPool(host: String, port: Int) {
  private val pool = new ConcurrentLinkedQueue[Socket]()
  private val activeCount = new atomic.AtomicInteger(0)

  def acquire(): Socket = {
    val existing = pool.poll()
    if (existing != null && !existing.isClosed) {
      existing
    } else {
      val sock = new Socket()
      sock.connect(new InetSocketAddress(host, port), HttpConfig.CONNECT_TIMEOUT_MS)
      sock.setSoTimeout(HttpConfig.READ_TIMEOUT_MS)
      activeCount.incrementAndGet()
      sock
    }
  }

  def release(sock: Socket): Unit = {
    if (!sock.isClosed && pool.size() < HttpConfig.MAX_POOL_SIZE) {
      pool.offer(sock)
    } else {
      sock.close()
      activeCount.decrementAndGet()
    }
  }
}

class HttpRequestBuilder {
  private var method: String = "POST"
  private var path: String = "/"
  private var headers: mutable.ListBuffer[(String, String)] = mutable.ListBuffer()
  private var body: Option[Array[Byte]] = None

  def setMethod(m: String): HttpRequestBuilder = { method = m; this }
  def setPath(p: String): HttpRequestBuilder = { path = p; this }
  def addHeader(name: String, value: String): HttpRequestBuilder = {
    headers += ((name, value)); this
  }
  def setBody(b: Array[Byte]): HttpRequestBuilder = { body = Some(b); this }

  def build(): Array[Byte] = {
    val sb = new StringBuilder()
    sb.append(s"$method $path HTTP/1.1\r\n")

    // Add content-length based on body
    body.foreach { b =>
      sb.append(s"Content-Length: ${b.length}\r\n")
    }

    // Append user-specified headers
    headers.foreach { case (name, value) =>
      sb.append(s"$name: $value\r\n")
    }

    sb.append("\r\n")
    val headerBytes = sb.toString.getBytes("ISO-8859-1")
    body match {
      case Some(b) => headerBytes ++ b
      case None => headerBytes
    }
  }
}

trait TelemetrySerializer {
  def serialize(readings: Map[String, Double]): Array[Byte]
  def contentType: String
}

class JsonTelemetrySerializer extends TelemetrySerializer {
  override def serialize(readings: Map[String, Double]): Array[Byte] = {
    val json = readings.map { case (k, v) => s""""$k":$v""" }.mkString("{", ",", "}")
    json.getBytes("UTF-8")
  }
  override def contentType: String = "application/json"
}

class FirmwareHttpClient(host: String, port: Int) {
  private val pool = new ConnectionPool(host, port)
  private val serializer: TelemetrySerializer = new JsonTelemetrySerializer()
  private val deviceId: String = sys.env.getOrElse("DEVICE_ID", "iot-sensor-001")

  /**
   * Sends telemetry data to the cloud endpoint.
   * Uses connection pooling for efficiency on constrained IoT hardware.
   */
  def sendTelemetry(readings: Map[String, Double]): Boolean = {
    val payload = serializer.serialize(readings)
    val request = buildTelemetryRequest(payload)
    executeWithRetry(request, maxRetries = 2)
  }

  private def buildTelemetryRequest(payload: Array[Byte]): Array[Byte] = {
    val builder = new HttpRequestBuilder()
      .setMethod("POST")
      .setPath(HttpConfig.FIRMWARE_ENDPOINT)
      .addHeader("Host", host)
      .addHeader("Connection", "keep-alive")
      .addHeader("X-Device-ID", deviceId)
      .addHeader("Content-Type", serializer.contentType)
      .addHeader("Transfer-Encoding", computeTransferEncoding(payload))
      .setBody(payload)
    builder.build()
  }

  /**
   * Determines transfer encoding based on payload characteristics.
   * For small payloads on IoT devices, identity encoding is preferred
   * to minimize processing overhead.
   */
  private def computeTransferEncoding(payload: Array[Byte]): String = {
    if (payload.length > 4096) "chunked" else "identity"
  }

  private def executeWithRetry(request: Array[Byte], maxRetries: Int): Boolean = {
    var attempts = 0
    while (attempts <= maxRetries) {
      val sock = pool.acquire()
      try {
        val out: OutputStream = sock.getOutputStream
        out.write(request)
        out.flush()

        val reader = new BufferedReader(new InputStreamReader(sock.getInputStream))
        val statusLine = reader.readLine()
        if (statusLine != null && statusLine.contains("200")) {
          drainResponse(reader)
          pool.release(sock)
          return true
        } else {
          drainResponse(reader)
          pool.release(sock)
          attempts += 1
        }
      } catch {
        case _: Exception =>
          try { sock.close() } catch { case _: Exception => }
          attempts += 1
      }
    }
    false
  }

  private def drainResponse(reader: BufferedReader): Unit = {
    var contentLength = 0
    var line = reader.readLine()
    while (line != null && line.nonEmpty) {
      if (line.toLowerCase.startsWith("content-length:")) {
        contentLength = line.substring(15).trim.toInt
      }
      line = reader.readLine()
    }
    if (contentLength > 0) {
      val buf = new Array[Char](contentLength)
      reader.read(buf, 0, contentLength)
    }
  }
}

object IoTTelemetryDaemon {
  def main(args: Array[String]): Unit = {
    val cloudHost = sys.env.getOrElse("CLOUD_HOST", "telemetry.iotcloud.internal")
    val cloudPort = sys.env.getOrElse("CLOUD_PORT", "8080").toInt
    val client = new FirmwareHttpClient(cloudHost, cloudPort)

    // Simulated sensor loop
    while (true) {
      val readings = Map(
        "temperature" -> (20.0 + math.random() * 15.0),
        "humidity" -> (30.0 + math.random() * 50.0),
        "pressure" -> (980.0 + math.random() * 40.0)
      )
      client.sendTelemetry(readings)
      Thread.sleep(5000)
    }
  }
}
